package ir.hamrahyar.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.Locale;
public class MainActivity extends Activity{
 int ink=Color.rgb(32,54,52),teal=Color.rgb(40,125,114),bg=Color.rgb(244,247,246);SharedPreferences prefs;LinearLayout root;
 GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);return d;}
 TextView txt(String s,int z,int c,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(b)t.setTypeface(null,1);t.setGravity(Gravity.RIGHT);t.setTextDirection(View.TEXT_DIRECTION_RTL);return t;}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return l;}
 void start(String title,String sub){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(bg);root=col();root.setPadding(20,22,20,28);sc.addView(root);setContentView(sc);root.addView(txt("همراه‌یار",27,ink,true));TextView s=txt(sub,13,Color.GRAY,false);s.setPadding(0,3,0,18);root.addView(s);TextView h=txt(title,21,ink,true);h.setPadding(0,0,0,14);root.addView(h);}
 void card(String h,String d,Runnable r){LinearLayout c=col();c.setPadding(16,15,16,15);c.setBackground(shape(Color.WHITE,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=10;root.addView(c,p);c.addView(txt(h,17,ink,true));TextView t=txt(d,13,Color.GRAY,false);t.setPadding(0,5,0,0);c.addView(t);if(r!=null)c.setOnClickListener(v->r.run());}
 EditText field(String hint){EditText e=new EditText(this);e.setSingleLine();e.setHint(hint);e.setTextSize(15);e.setBackground(shape(Color.WHITE,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=9;root.addView(e,p);return e;}
 void btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(-1);b.setBackground(shape(teal,15));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,54);p.bottomMargin=12;root.addView(b,p);b.setOnClickListener(v->r.run());}
 void nav(){TextView t=txt("‹ بازگشت به خانه",14,teal,true);t.setGravity(Gravity.CENTER);t.setPadding(0,20,0,0);root.addView(t);t.setOnClickListener(v->home());}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);prefs=getSharedPreferences("hamrah_yar",0);home();}
 String two(int n){return n<10?"0"+n:""+n;}
 int[] jalali(int gy,int gm,int gd){int[] gdm={0,31,59,90,120,151,181,212,243,273,304,334};if(gm<1||gm>12||gd<1||gd>31)throw new IllegalArgumentException();int y=gy-1600,m=gm-1,d=gd-1;int g=y*365+(y+3)/4-(y+99)/100+(y+399)/400+gdm[m]+d;if(m>1&&((gy%4==0&&gy%100!=0)||gy%400==0))g++;int j=g-79,np=j/12053;j%=12053;int jy=979+33*np+4*(j/1461);j%=1461;if(j>=366){jy+=(j-1)/365;j=(j-1)%365;}int jm,jd;if(j<186){jm=1+j/31;jd=1+j%31;}else{jm=7+(j-186)/30;jd=1+(j-186)%30;}return new int[]{jy,jm,jd};}
 void home(){start("دستیار زندگی روزمره","نسخه توسعه‌ای · اطلاعات آزمایشی روی همین گوشی");Calendar c=Calendar.getInstance();int[] j=jalali(c.get(1),c.get(2)+1,c.get(5));card("امروز · "+j[0]+"/"+two(j[1])+"/"+two(j[2]),"تاریخ میلادی: "+c.get(1)+"/"+two(c.get(2)+1)+"/"+two(c.get(5)),()->calendar());card("تقویم و مناسبت‌ها","تبدیل تاریخ میلادی به شمسی",()->calendar());card("سلامت و تندرستی","ثبت قد و وزن و محاسبه BMI",()->health());card("یادآورها","ثبت و حذف یادآور محلی",()->reminders());card("مالی و پرداخت قبوض","بودجه، اقساط و پرداخت از طریق ارائه‌دهنده مجاز · در حال توسعه",()->coming("مالی و قبوض"));card("آموزش و درس","برنامه درسی، تکالیف و امتحان · در حال توسعه",()->coming("آموزش"));card("نقشه و طبیعت‌گردی","نقشه آفلاین و مسیرها · در حال توسعه",()->coming("نقشه و طبیعت‌گردی"));card("هتل و مراکز درمانی","اطلاعات به‌روز و منبع‌دار · در حال توسعه",()->coming("خدمات شهری"));}
 void calendar(){start("تقویم و تبدیل تاریخ","تبدیل محاسباتی میلادی به شمسی");EditText y=field("سال میلادی مثل 2026"),m=field("ماه 1 تا 12"),d=field("روز");TextView out=txt("نتیجه تبدیل اینجا نمایش داده می‌شود.",16,teal,true);root.addView(out);btn("تبدیل به شمسی",()->{try{int[] a=jalali(Integer.parseInt(y.getText().toString()),Integer.parseInt(m.getText().toString()),Integer.parseInt(d.getText().toString()));out.setText("تاریخ شمسی: "+a[0]+"/"+two(a[1])+"/"+two(a[2]));}catch(Exception e){out.setText("تاریخ واردشده معتبر نیست.");}});card("گام بعدی","تقویم ماهانه، تبدیل معکوس، اختلاف روزها و مناسبت‌های چندکشوری در مراحل بعد اضافه می‌شوند.",null);nav();}
 void health(){start("سلامت و تندرستی","BMI ابزار غربالگری است، نه تشخیص پزشکی");EditText h=field("قد به سانتی‌متر"),w=field("وزن به کیلوگرم");TextView out=txt("نتیجه اینجا نمایش داده می‌شود.",16,teal,true);root.addView(out);btn("محاسبه BMI",()->{try{double a=Double.parseDouble(h.getText().toString())/100,b=Double.parseDouble(w.getText().toString()),v=b/(a*a);out.setText(String.format(Locale.US,"BMI: %.1f",v));}catch(Exception e){out.setText("قد و وزن معتبر وارد کن.");}});card("حریم خصوصی","اطلاعات برای این محاسبه ذخیره نمی‌شود. پرونده سلامت و سلامت روان نیازمند طراحی امن و محتوای معتبر است.",null);nav();}
 void reminders(){start("یادآورهای من","ذخیره محلی روی همین گوشی");LinearLayout list=col();root.addView(list);Set<String> set=new HashSet<>(prefs.getStringSet("items",new HashSet<String>()));for(String s:set){TextView t=txt("• "+s,15,ink,false);t.setPadding(8,12,8,12);list.addView(t);t.setOnLongClickListener(v->{set.remove(s);prefs.edit().putStringSet("items",set).apply();reminders();return true;});}btn("افزودن یادآور",()->{EditText e=new EditText(this);e.setHint("عنوان و تاریخ دلخواه");new AlertDialog.Builder(this).setTitle("یادآور جدید").setView(e).setNegativeButton("انصراف",null).setPositiveButton("ذخیره",(x,y)->{String s=e.getText().toString().trim();if(!s.isEmpty()){set.add(s);prefs.edit().putStringSet("items",set).apply();reminders();}}).show();});card("محدودیت فعلی","اعلان خودکار در زمان سررسید هنوز پیاده‌سازی نشده است.",null);nav();}
 void coming(String name){start(name,"این بخش در نقشه راه توسعه قرار دارد");card("در حال آماده‌سازی","این قابلیت هنوز به سرویس واقعی متصل نیست؛ بنابراین پرداخت، رزرو یا اطلاعات زنده‌ای نمایش داده نمی‌شود.",null);nav();}
}